class Solution {
public:
    bool isPal(long long x) {
        string s = to_string(x);
        int i = 0, j = s.length() - 1;
        while (i < j) if (s[i++] != s[j--]) return false;
        return true;
    }

    int superpalindromesInRange(string left, string right) {
        long long L = stoll(left), R = stoll(right);
        int count = 0;
        for (int k = 1; k < 100000; k++) {
            string s = to_string(k);
            string rev = s.substr(0, s.length() - 1);
            reverse(rev.begin(), rev.end());
            long long p = stoll(s + rev);
            if (p > 1000000000LL) break;
            long long sq = p * p;
            if (sq > R) break;
            if (sq >= L && isPal(sq)) count++;
        }
        for (int k = 1; k < 100000; k++) {
            string s = to_string(k);
            string rev = s;
            reverse(rev.begin(), rev.end());
            long long p = stoll(s + rev);
            if (p > 1000000000LL) break;
            long long sq = p * p;
            if (sq > R) break;
            if (sq >= L && isPal(sq)) count++;
        }
        return count;
    }
};

