        for (int k = 1; k < 100000; k++) {
            String s = Integer.toString(k);
            StringBuilder sb = new StringBuilder(s.substring(0, s.length() - 1)).reverse();
            long p = Long.parseLong(s + sb.toString());
            if (p > 1000000000L) break;
            long sq = p * p;
            if (sq > R) break;
            if (sq >= L && isPal(sq)) count++;
        }
        for (int k = 1; k < 100000; k++) {
